var t=[{title:`Wat elk gebied doet`,text:`De borstwervelkolom is het middelste deel van je rug en laat je draaien en strekken. Het schoudercomplex omvat het kogelgewricht en het schouderblad dat over de ribbenkast glijdt. Reiken boven het hoofd hangt af van meerdere gebieden die samenwerken, dus het test meer dan de flexibiliteit van het schoudergewricht.`},{title:`Verken comfortabele beweging`,text:`Een open-book-rotatie draait je bovenlichaam zachtjes terwijl je heupen vrij stil blijven. Beheerste armcirkels oefenen schouderbeweging, en cat-cow beweegt de wervelkolom in een rustig tempo door flexie en extensie. Beweeg langzaam, adem normaal en forceer de eindpositie niet.`},{title:`Mobiliteit in je lifts`,text:`Persen boven het hoofd kan soepeler voelen als je ribben, schouderbladen en armen samen bewegen. Laat je schouderbladen bij rows natuurlijk bewegen; je hoeft ze niet de hele tijd naar achteren vast te zetten. Streef naar soepele controle in de oefening die je koos. Er is geen enkele starre houding die iedereen moet nabootsen.`},{title:`Mobiliteit plus kracht`,text:`Lichte persen, wall slides, rows en beheerste carries bouwen samen bruikbaar bereik en coördinatie op. Alleen rekken kan de passieve flexibiliteit verbeteren zonder je volledige controle onder belasting te geven. Voelt een oefening instabiel of onprettig, verander dan de grip, hoek of het bewegingsbereik.`},{title:`TrainUp gebruiken`,text:`Hindert werk boven het hoofd je schouder, voeg de schouder dan toe als beperking in Profiel, met een notitie. Het schema kiest alleen oefeningen die bij je beperkingen passen. Ga bij nieuwe, aanhoudende of verergerende schouderpijn naar een arts of fysiotherapeut in plaats van op algemene mobiliteitsoefeningen te vertrouwen.`}];var i=[{label:`ACE 2026: mobiliteit versus flexibiliteit`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`ACE 2026: praktische richtlijnen voor rekken`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`ACE-oefeningenbibliotheek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var r={sections:t,sources:i};export{r as default,t as sections,i as sources};